INSERT INTO cu_site_block (site_block_id, block_key, body, note) VALUES
    ('01a0c450-6c00-7000-8000-000000000000', 'site.tagline', '{"en": "We document individual experiences, not entire cultures."}'::jsonb, 'Footer and page descriptions: the project''s central idea.'),
    ('01a0c450-6c01-7001-8000-000000000001', 'home.hero.title', '{"en": "CULTURE, UNFILTERED"}'::jsonb, 'Home page: the title of the hero section.'),
    ('01a0c450-6c02-7002-8000-000000000002', 'home.hero.subtitle', '{"en": "Six teenagers. Six places. Hundreds of ways to experience culture."}'::jsonb, 'Home page: the subtitle under the title. Keep the numbers in line with the participants shown.'),
    ('01a0c450-6c03-7003-8000-000000000003', 'home.cta.explore', '{"en": "EXPLORE THE STORIES"}'::jsonb, 'Home page: the primary button, to the stories.'),
    ('01a0c450-6c04-7004-8000-000000000004', 'home.cta.method', '{"en": "HOW WE WORK"}'::jsonb, 'Home page: the secondary button, to our method.'),
    ('01a0c450-6c05-7005-8000-000000000005', 'home.question', '{"en": "Can one person represent an entire culture?"}'::jsonb, 'Home page: the central question after the hero.'),
    ('01a0c450-6c06-7006-8000-000000000006', 'home.answer', '{"en": "Probably not. That''s why we''re not trying to."}'::jsonb, 'Home page: the answer under the central question.'),
    ('01a0c450-6c07-7007-8000-000000000007', 'home.intro', '{"en": "Each of us documents our own experience of culture, identity, language, family, school, food and everyday life. None of us claims to speak for a whole country: what you will find here are individual experiences, side by side, so that you can compare them."}'::jsonb, 'Home page: the short explanation under the answer.'),
    ('01a0c450-6c08-7008-8000-000000000008', 'method.ethnography', '{"en": "Ethnography is the study of how people live, from the inside: watching, listening, asking and taking part. **Digital ethnography** does this with the tools we already carry: short videos, photographs, recorded interviews and written reflections, shared online so that others can look closely too."}'::jsonb, 'Our method: What is digital ethnography?'),
    ('01a0c450-6c09-7009-8000-000000000009', 'method.approach', '{"en": "We use observation, interviews, video, photography, personal reflection and cross-cultural discussion."}'::jsonb, 'Our method: Our approach.'),
    ('01a0c450-6c0a-700a-8000-00000000000a', 'method.reflexivity', '{"en": "Our own backgrounds shape what we notice and how we interpret other people''s experiences. We try to say where we stand, and we ask each other what we missed."}'::jsonb, 'Our method: Reflexivity.'),
    ('01a0c450-6c0b-700b-8000-00000000000b', 'method.emic-etic', '{"en": "An **emic** perspective describes a way of life from the inside, in the terms of the people who live it. An **etic** perspective describes it from the outside, often by comparing it with others. We try to keep both in view, and to say which one we are using."}'::jsonb, 'Our method: Emic and etic perspectives.'),
    ('01a0c450-6c0c-700c-8000-00000000000c', 'method.representation', '{"en": "Countries are not culturally uniform, and no single person can speak for everyone who lives in one. **One person cannot represent an entire culture.** That is why every story here belongs to a person, and names the place they speak from."}'::jsonb, 'Our method: Cultural representation.'),
    ('01a0c450-6c0d-700d-8000-00000000000d', 'method.principle.consent', '{"en": "Everyone who appears in our work has agreed to it, and can change their mind."}'::jsonb, 'Our method: the principle CONSENT.'),
    ('01a0c450-6c0e-700e-8000-00000000000e', 'method.principle.context', '{"en": "We explain where, when and why something was recorded, so that it is not read out of context."}'::jsonb, 'Our method: the principle CONTEXT.'),
    ('01a0c450-6c0f-700f-8000-00000000000f', 'method.principle.respect', '{"en": "We describe other people''s lives the way we would want our own to be described."}'::jsonb, 'Our method: the principle RESPECT.'),
    ('01a0c450-6c10-7010-8000-000000000010', 'method.principle.reflexivity', '{"en": "We think about how our own background shapes what we see."}'::jsonb, 'Our method: the principle REFLEXIVITY.'),
    ('01a0c450-6c11-7011-8000-000000000011', 'method.principle.responsible-representation', '{"en": "We speak for ourselves, not for our countries, and we avoid stereotypes."}'::jsonb, 'Our method: the principle RESPONSIBLE REPRESENTATION.'),
    ('01a0c450-6c12-7012-8000-000000000012', 'about.project', '{"en": "Culture, Unfiltered is a youth-led international digital ethnography project. Students from different places document how young people experience culture, identity, language, family, school, food, belonging and everyday life, and compare what they discover."}'::jsonb, 'About: the project.'),
    ('01a0c450-6c13-7013-8000-000000000013', 'about.privacy', '{"en": "We publish first names or chosen names only, never surnames, schools or exact locations. Nothing about a participant is published without their consent (and, for those under 18, their guardian''s). Participants can withdraw their consent at any time; their contributions are then taken offline."}'::jsonb, 'About: privacy. Keep it in line with the consent rules in the editor guide.');
